@available(macOS 10.15, *)
@MainActor
class ViewModel: NSObject, ObservableObject {
    private var radio: BleByteRadio?
    private var shimmer3Protocol: Shimmer3Protocol?
    private var verisenseProtocol: VerisenseProtocol?

    private var bluetoothManager: BluetoothManager?
    private var centralManager: CBCentralManager?
    @Published var isScanning = false

    // MARK: - UI-facing status (added for ContentView; does not affect SDK call logic)
    @Published var isDev1Connected = false
    @Published var isDev2Connected = false
    @Published var statusMessage: String = "Ready"
    @Published var activityLog: [String] = []

    private func log(_ message: String) {
        let timestamp = DateFormatter.localizedString(from: Date(), dateStyle: .none, timeStyle: .medium)
        activityLog.insert("[\(timestamp)] \(message)", at: 0)
        if activityLog.count > 50 {
            activityLog.removeLast()
        }
        statusMessage = message
    }

    public override init() {
        super.init()
        self.centralManager = CBCentralManager()//(delegate: self, queue: nil)
        //self.radio = BleByteRadio(deviceName: "Verisense-21082701B799",cbcentralmanager: centralManager!)
        self.bluetoothManager = BluetoothManager(centralmanager: self.centralManager!)
        //radio.delegate = self
    }
    func test(){
        //let printer = Test()
        //let printer = BluetoothManager()
        //printer.sayHello();


        //radio.startScanningAndConnectifFound(timeout: 20000)
        //820702820702radio!.startScanning(timeout: 20000)
        let started = bluetoothManager?.startScanning(uuid: BleByteRadio.VERISENSE_RBL_SERVICE_UUID, timeout: 2) ?? false
        isScanning = started
        log(started ? "Scanning for Verisense (Dev1)..." : "Failed to start scan (Bluetooth not ready)")
        if started {
            DispatchQueue.main.asyncAfter(deadline: .now() + 2) { [weak self] in
                self?.isScanning = false
            }
        }

    }

    func connect()async{
        var peripheral = bluetoothManager?.getPeripheral(deviceName: "Verisense-21082701B799")
        self.radio = BleByteRadio(deviceName: "Verisense-21082701B799",cbperipheral: peripheral!,bluetoothManager: bluetoothManager!)
        let result = await radio?.connect()
        verisenseProtocol = VerisenseProtocol(radio: self.radio!)
        isDev1Connected = (result == true)
        log(isDev1Connected ? "Connected to Verisense (Dev1)" : "Failed to connect to Verisense (Dev1)")
    }

    func disconnect()async{
        var peripheral = bluetoothManager?.getPeripheral(deviceName: "Verisense-21082701B799")
        self.radio = BleByteRadio(deviceName: "Verisense-21082701B799",cbperipheral: peripheral!,bluetoothManager: bluetoothManager!)
        let result = await radio?.disconnect()
        isDev1Connected = false
        log(result == true ? "Disconnected Verisense (Dev1)" : "Disconnect (Dev1) completed")
    }
    func sendReadProductionCommand() async{

            let production = await verisenseProtocol!.sendReadProductionCommand()
            let status = await verisenseProtocol!.sendReadStatusCommand()
            log("Read production info: \(production == true ? "OK" : "failed"); status: \(status == true ? "OK" : "failed")")

    }

    func sendSpeedTestCommand() async {
        await verisenseProtocol?.sendReadMemoryLookupTableRequest()
        log("Speed test command sent (Dev1)")
    }

    func scanShimmer3(){
        let started = bluetoothManager?.startScanning(deviceName: "Shimmer3-67FC",timeout: 10) ?? false
        isScanning = started
        log(started ? "Scanning for Shimmer3 (Dev2)..." : "Failed to start scan (Bluetooth not ready)")
        if started {
            DispatchQueue.main.asyncAfter(deadline: .now() + 10) { [weak self] in
                self?.isScanning = false
            }
        }

    }

    func connectDev2() async{
        var peripheral = bluetoothManager?.getPeripheral(deviceName: "Shimmer3-67FC")
        self.radio = BleByteRadio(deviceName: "Shimmer3-67FC",cbperipheral: peripheral!,bluetoothManager: bluetoothManager!)
        shimmer3Protocol = Shimmer3Protocol(radio: self.radio!)
        let result = await shimmer3Protocol?.connect()
        isDev2Connected = (result == true)
        log(isDev2Connected ? "Connected to Shimmer3 (Dev2)" : "Failed to connect to Shimmer3 (Dev2)")

    }
    func disconnectDev2() async{
            let result = await shimmer3Protocol!.disconnect()
            isDev2Connected = false
            log(result == true ? "Disconnected Shimmer3 (Dev2)" : "Disconnect (Dev2) completed")

    }

    func sendInquiryCommandDev2() async {

    }

    func sendStartStreamingCommandDev2() async {
         let result = await shimmer3Protocol!.sendStartStreamingCommand()
         log(result == true ? "Started streaming (Dev2)" : "Start streaming failed (Dev2)")

    }

    func sendStopStreamingCommandDev2() async {
            shimmer3Protocol!.sendStopStreamingCommand()
            log("Stop streaming requested (Dev2)")

    }
